    {
      "id": "T2",
      "result": "fail",
      "evidence": "The core function (retrieving a user's Facebook group posts) depends entirely on Facebook/Meta, which deprecated and removed the Groups API (permissions publish_to_groups, groups_access_member_info) starting Jan 2024, fully removed by April 2024, eliminating the only sanctioned path for third-party apps to read group feeds. The only remaining technical path is browser automation/scraping of a logged-in session, which Meta's Terms of Service and Automated Data Collection Terms explicitly prohibit ('You may not access or collect data from our Products using automated means without our prior permission'). Current open-source projects attempting this (e.g., fbtool) explicitly state 'This is against Facebook's ToS' and warn of account suspension risk.",
      "source_url": "https://techcrunch.com/2024/02/05/meta-cuts-off-third-party-access-to-facebook-groups-leaving-developers-and-customers-in-disarray/"
    },
    {
      "id": "T3",
      "result": "pass",
      "evidence": "No physical inventory involved; purely a software client.",
      "source_url": null
    },
    {
      "id": "T7",
      "result": "pass",
      "evidence": "No physical infrastructure or capital equipment required beyond standard software development.",
      "source_url": null
    }
  ],
  "flags": [
    { "id": "T4", "evidence": "Likely a consumer self-serve app; no enterprise sales needed, so this flag does not apply strongly." },
    { "id": "T5", "evidence": "Consumer app with no inherent per-transaction human support requirement." },
    { "id": "T6", "evidence": "Even if technically built via scraping, distribution risk (Apple/Google app store rejection, Facebook account bans) could block reaching paying customers within 90 days." }
  ],
  "competitors": [
    {
      "name": "fbtool",
      "url": "https://github.com/mharizanov/fbtool",
      "relationship": "direct",
      "pricing": null,
      "evidence": "Open-source tool that scrapes Facebook groups via browser automation because 'Facebook has no API for groups'; explicitly states this is against Facebook's ToS."
    },
    {
      "name": "Groups Watcher",
      "url": "https://www.groupswatcher.com/",
      "relationship": "direct",
      "pricing": "Professional plan (paid tiers)",
      "evidence": "Chrome extension/service monitoring Facebook groups; warns that automation on personal accounts risks account restriction and offers a hosted alternative using their own accounts."
    },
    {
      "name": "fb-rss",
      "url": "https://codeberg.org/johnsturgeon/fb-rss",
      "relationship": "direct",
      "pricing": null,
      "evidence": "Python daemon generating RSS feeds from Facebook groups via Playwright browser session (no API keys), confirming no sanctioned API exists for this use case."
    },
    {
      "name": "Facebook native 'Feeds' tab",
      "url": "https://buzzfeednews.com/amphtml/katienotopoulos/facebook-chronological-home-feed",
      "relationship": "adjacent",
      "pricing": "Free (built into Facebook app)",
      "evidence": "Facebook itself launched a chronological 'Feeds' view covering Friends, Groups, and Pages in 2022, reducing the unique value of an external client."
    }
  ],
  "queries": {
    "exa": [
      "third party app chronological Facebook group feed client",
      "Facebook API access revoked third party app group content"
    ],
    "brave": [
      "Facebook Graph API groups access deprecated third party apps",
      "app to see Facebook group posts chronological order not algorithm",
      "Facebook terms of service scraping automated data collection prohibited"
    ]
  },
  "proposed_variant": {
    "idea": "A digest/summary tool that uses officially permitted, user-authorized browser extension technology or Facebook's own in-app 'Feeds' chronological view as a UX layer, rather than independently retrieving group content via API or scraping.",
    "reason": "Facebook's Groups API is fully deprecated, and scraping violates ToS, so any viable variant must either operate as a thin UX wrapper around Facebook's existing native surfaces or abandon reliance on unauthorized data extraction, which fundamentally changes the product's value proposition."
  },
